'use client';
import { useRef, type CSSProperties } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { Fold, Seg, Swap } from '../lib/motion';
import '../designme.css';
import './run-queue.css';

export type RunState = 'queued' | 'running' | 'failed' | 'done';

export interface RunStep {
  label: string;
  state: RunState;
  /** What the step came to, shown once it is done, like "3 of 3" or "4 articles" */
  meta?: string;
}

export interface RunJob {
  /** Keeps the job's row when the list changes order. Defaults to the title */
  id?: string;
  /** What the job is, like "Draft the launch email" */
  title: string;
  /** Who does it, like "Copy agent", under the title */
  agent?: string;
  /** The icon on the job's badge. Defaults to a spark */
  icon?: IconName;
  state: RunState;
  /** How far the job is, 0 to 1. Defaults to the share of its steps that are done */
  progress?: number;
  /** The time at the end of the row: when a waiting job starts ("in ~4s"), what is left of a running one ("12s left") or how long a done one took ("4.2s") */
  time?: string;
  /** The line after the agent while it runs. Defaults to the step running, or the one that failed */
  note?: string;
  steps?: RunStep[];
}

export type RunQueueDensity = 'detailed' | 'compact';

export interface RunQueueProps {
  jobs: RunJob[];
  /** The queue's name over its status line */
  title?: string;
  /** Overrides the status line. Defaults to "1 of 4 done", "1 step failed, waiting for Retry" or "All 4 done" */
  status?: string;
  /** The line under "All 4 jobs done" once every job is done, like "18.4s in all · 1 retry" */
  summary?: string;
  /** detailed lists the running job's steps, compact folds them away. Leave it out to let the switch change it */
  density?: RunQueueDensity;
  defaultDensity?: RunQueueDensity;
  onDensityChange?: (density: RunQueueDensity) => void;
  /** Called by the Retry button on a failed step, with the job's and the step's index. Without it, failed steps show no button */
  onRetry?: (job: number, step: number) => void;
  /** Sits flat in a chat thread, with no card. Defaults to false: the queue on its card, as on designme.dev */
  bare?: boolean;
  className?: string;
}

const live = (s: RunState) => s === 'running' || s === 'failed';
const share = (j: RunJob) => j.progress ?? (j.steps?.length ? j.steps.filter(s => s.state === 'done').length / j.steps.length : j.state === 'done' ? 1 : 0);

function StepGlyph({ state }: { state: RunState }) {
  if (state === 'running') return <span className="dm-spin" aria-hidden="true" />;
  if (state === 'failed') return <Icon name="x" size="xs" />;
  if (state === 'done') return <Icon name="check" size="xs" />;
  return <span className="dm-dot" aria-hidden="true" />;
}

/** A queue of agent jobs: the one running, raised with its steps, progress and time left; the ones up next; and the ones done. */
export function RunQueue({ jobs, title = 'Run queue', status, summary, density, defaultDensity = 'detailed', onDensityChange, onRetry, bare = false, className }: RunQueueProps) {
  const [dens, setDens] = useControllable(density, defaultDensity, onDensityChange);
  const reduce = useReducedMotion();
  const box = useRef<HTMLDivElement>(null);
  const done = jobs.filter(j => j.state === 'done').length, fin = jobs.length > 0 && done === jobs.length;
  const failed = jobs.some(j => j.state === 'failed');
  const line = status ?? (fin ? `All ${jobs.length} done` : failed ? '1 step failed, waiting for Retry' : `${done} of ${jobs.length} done`);
  const keyOf = (j: RunJob) => j.id ?? j.title;
  const part = (s: RunState) => live(s) ? 'run' : s === 'done' ? 'done' : 'next';

  /* a job that moves to another part of the queue glides there from where it was, and the jobs it passes glide with it */
  const was = useRef(new Map<string, { part: string; top: number; left: number }>());
  useIsoLayoutEffect(() => {
    const el = box.current; if (!el) return;
    const moved = jobs.some(j => { const w = was.current.get(keyOf(j)); return w && w.part !== part(j.state); });
    el.querySelectorAll<HTMLElement>('.dm-rq-j[data-k]').forEach(row => {
      const k = row.dataset.k!, w = was.current.get(k), b = row.getBoundingClientRect();
      if (moved && w && !reduce) { const dx = w.left - b.left, dy = w.top - b.top;
        if (Math.abs(dx) + Math.abs(dy) > 1) row.animate([{ transform: `translate(${dx}px,${dy}px)` }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(.22,1,.36,1)' }); }
      was.current.set(k, { part: row.dataset.p!, top: b.top, left: b.left });
    });
  }, [jobs.map(j => keyOf(j) + ':' + part(j.state)).join()]);

  const row = (j: RunJob, ji: number) => {
    const p = Math.max(0, Math.min(1, share(j))), s = j.state === 'running' ? 'run' : j.state === 'failed' ? 'fail' : j.state === 'done' ? 'done' : 'wait';
    const at = j.steps?.find(x => x.state === 'failed') ?? j.steps?.find(x => x.state === 'running');
    const note = live(j.state) ? j.note ?? at?.label : undefined;
    return (
      <li key={keyOf(j)} className="dm-rq-j" data-s={s} data-k={keyOf(j)} data-p={part(j.state)}>
        <div className="dm-rq-jh">
          <span className="dm-rq-av" aria-hidden="true"><Icon name={j.icon ?? 'spark'} /></span>
          <span className="dm-rq-jt"><b>{j.title}</b><Swap className="dm-rq-js">{[j.agent, note].filter(Boolean).join(' · ')}</Swap></span>
          <span className="dm-rq-jm dm-num">
            {j.time && <span>{j.time}</span>}
            {j.state === 'done' && <span className="dm-ok"><Icon name="check" size="xs" /></span>}
          </span>
        </div>
        <div className="dm-rq-jb" aria-hidden="true">
          <div className="dm-rq-bar"><i style={{ '--dm-p': p } as CSSProperties} /></div>
          <span className="dm-rq-pc dm-num">{Math.round(p * 100)}%</span>
        </div>
        <Fold open={dens === 'detailed' && live(j.state) && !!j.steps?.length} className="dm-rq-sf">
          <ul className="dm-rq-steps">
            {j.steps?.map((x, si) => (
              <li key={si} className={cx('dm-rq-sp', x.state === 'queued' ? 'dm-wait' : x.state === 'running' ? 'dm-run' : x.state === 'failed' ? 'dm-fail' : 'dm-done')}>
                <span className="dm-g"><StepGlyph state={x.state} /></span>
                <span>{x.label}</span>
                <span className="dm-m">
                  {x.state === 'failed' && onRetry
                    ? <button type="button" className="dm-rq-retry dm-enter" onClick={() => onRetry(ji, si)}>Retry</button>
                    : x.state === 'done' && x.meta ? <Swap>{x.meta}</Swap> : null}
                </span>
              </li>
            ))}
          </ul>
        </Fold>
      </li>
    );
  };
  const of = (ps: string) => jobs.map((j, ji) => part(j.state) === ps ? row(j, ji) : null);
  const waiting = jobs.some(j => part(j.state) === 'next');

  return (
    <div ref={box} data-dm="" className={cx('dm-rq', !bare && 'dm-panel dm-keep', fin && 'dm-fin', className)} style={bare ? { paddingInline: 0 } : undefined}>
      <div className="dm-rq-h">
        <div className="dm-rq-ht"><b>{title}</b><Swap className="dm-rq-st dm-num">{line}</Swap></div>
        <Seg label="Density" value={dens} onChange={setDens} options={[{ value: 'detailed', label: 'Detailed' }, { value: 'compact', label: 'Compact' }]} />
      </div>
      <div className="dm-rq-tot" aria-hidden="true">
        {jobs.map(j => <i key={keyOf(j)} className={cx(j.state === 'failed' && 'dm-fail')}><b style={{ '--dm-p': Math.max(0, Math.min(1, share(j))) } as CSSProperties} /></i>)}
      </div>
      <div className="dm-rq-b">
        <Fold open={fin} className="dm-rq-ff">
          <div className="dm-rq-sec">
            <div className={cx('dm-rq-fin', fin && 'dm-enter')}>
              <span className="dm-rq-av" aria-hidden="true"><Icon name="ok" /></span>
              <span className="dm-rq-jt"><b className="dm-rq-ft">{`All ${jobs.length} jobs done`}</b>{summary && <span className="dm-rq-js">{summary}</span>}</span>
            </div>
          </div>
        </Fold>
        <Fold open={!fin} className="dm-rq-rf">
          <div className="dm-rq-sec"><span className="dm-rq-l">Running</span><ul className="dm-rq-run" aria-label="Running">{of('run')}</ul></div>
        </Fold>
        <Fold open={!fin} className="dm-rq-nf">
          <div className="dm-rq-sec"><span className="dm-rq-l">Up next</span><ol className="dm-rq-next" aria-label="Up next">{waiting ? of('next') : null}</ol><p className="dm-rq-none">Nothing waiting</p></div>
        </Fold>
        <Fold open className="dm-rq-df">
          <div className="dm-rq-sec"><span className="dm-rq-l">Done <span className="dm-num">{done}</span></span><ul className="dm-rq-done" aria-label="Done">{done ? of('done') : null}</ul><p className="dm-rq-none">Nothing done yet</p></div>
        </Fold>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Run queue ---------- */
/* a queue of agent jobs in three parts, on one left edge: the job running, raised, with its agent, its steps, a progress
   bar and the time left; the jobs up next, each with its agent and when it should start; and the jobs done, each with how
   long it took and a green tick. A job glides from one part to the next as it moves, a part with nothing in it folds away,
   and when every job is done a summary takes the running job's place */
.dm-rq{display:flex;flex-direction:column;padding:var(--dm-s-3);text-align:left}
.dm-rq-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3)}
.dm-rq-ht{display:flex;flex-direction:column;min-width:0}
.dm-rq-ht b{font-weight:500}
.dm-rq-st{font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the whole queue at a glance: a part of the strip for each job, filled as it runs */
.dm-rq-tot{display:flex;gap:3px;margin-top:var(--dm-s-3)}
.dm-rq-tot i{flex:1;height:4px;border-radius:2px;background:var(--dm-line);overflow:hidden}
.dm-rq-tot b{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform .3s linear,background .3s}
.dm-rq-tot i.dm-fail b{background:var(--dm-bad)}
/* the end of the queue keeps the room it had and centres what is left in it */
.dm-rq-b{flex:1;display:flex;flex-direction:column}
.dm-rq.dm-fin .dm-rq-b{justify-content:center}
.dm-rq-sec{display:flex;flex-direction:column;gap:6px;padding-top:var(--dm-s-3)}
.dm-rq-l{display:flex;align-items:baseline;gap:6px;font-size:12px;color:var(--dm-muted)}
.dm-rq-l .dm-num{color:var(--dm-fg2)}
.dm-rq-none{display:none;align-items:center;min-height:40px;margin:0;font-size:12.5px;color:var(--dm-muted)}
.dm-rq-next:empty+.dm-rq-none,.dm-rq-done:empty+.dm-rq-none{display:flex}
.dm-rq-run,.dm-rq-next,.dm-rq-done{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px}
/* a job: its agent's badge, what it is and who does it, and its time */
.dm-rq-j{display:flex;flex-direction:column;border-radius:var(--dm-r-in);font-size:13px}
.dm-rq-jh{display:flex;align-items:center;gap:10px;min-height:40px}
.dm-rq-av{position:relative;width:28px;height:28px;border-radius:calc(9px * var(--dm-rk));display:grid;place-items:center;flex:none;background:var(--dm-chip);color:var(--dm-fg2);transition:background .3s,color .3s}
.dm-rq-av .dm-i{width:13px;height:13px;stroke-width:1.9}
.dm-rq-jt{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-rq-jt b{font-weight:400;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:color .3s}
.dm-rq-js{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-rq-jm{display:flex;align-items:center;gap:6px;flex:none;font-size:12px;color:var(--dm-muted);white-space:nowrap}
.dm-rq-jm .dm-ok{display:grid;color:var(--dm-ok)}
.dm-rq-jb{display:none;align-items:center;gap:10px;padding:0 0 2px 38px}
.dm-rq-bar{flex:1;height:4px;border-radius:2px;background:var(--dm-line);overflow:hidden}
.dm-rq-bar i{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform .2s linear}
.dm-rq-pc{width:32px;flex:none;font-size:12px;color:var(--dm-muted);text-align:right}
/* the job running: raised on the surface, its badge in the accent, with its progress and its steps */
.dm-rq-j:is([data-s="run"],[data-s="fail"]){padding:var(--dm-s-1) 10px 10px;background:var(--dm-surface);box-shadow:var(--dm-shadow);gap:6px}
.dm-rq-j:is([data-s="run"],[data-s="fail"]) .dm-rq-jb{display:flex}
.dm-rq-j:is([data-s="run"],[data-s="fail"]) .dm-rq-jt b{font-weight:500;color:var(--dm-fg)}
.dm-rq-j[data-s="run"] .dm-rq-av{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.dm-rq-j[data-s="done"] .dm-rq-jt b{color:var(--dm-fg2)}
/* a failed step turns the job red until Retry */
.dm-rq-j[data-s="fail"]{background:var(--dm-bad-bg);box-shadow:none}
.dm-rq-j[data-s="fail"] .dm-rq-av{background:var(--dm-surface);color:var(--dm-bad)}
.dm-rq-j[data-s="fail"] :is(.dm-rq-jt b,.dm-rq-jm,.dm-rq-pc){color:var(--dm-bad)}
.dm-rq-j[data-s="fail"] .dm-rq-js{color:var(--dm-fg2)}
.dm-rq-j[data-s="fail"] .dm-rq-bar{background:color-mix(in srgb,var(--dm-bad) 18%,transparent)}
.dm-rq-j[data-s="fail"] .dm-rq-bar i{background:var(--dm-bad)}
.dm-rq-steps{list-style:none;margin:0;padding:var(--dm-s-1) 0 0 38px;display:flex;flex-direction:column}
.dm-rq-sp{display:flex;align-items:center;gap:var(--dm-s-2);min-height:26px;font-size:12.5px;color:var(--dm-fg2)}
.dm-rq-sp .dm-g{width:14px;display:grid;place-items:center;flex:none}
.dm-rq-sp .dm-g .dm-spin{width:10px;height:10px}
.dm-rq-sp .dm-g .dm-dot{width:5px;height:5px;color:var(--dm-faint)}
.dm-rq-sp .dm-m{margin-left:auto;font-size:12px;color:var(--dm-muted)}
.dm-rq-sp.dm-wait{color:var(--dm-muted)}
.dm-rq-sp.dm-done .dm-g{color:var(--dm-ok)}
.dm-rq-sp.dm-fail,.dm-rq-sp.dm-fail .dm-g{color:var(--dm-bad)}
.dm-rq-retry{height:24px;padding:0 10px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-shadow);font-size:12px;font-weight:500;color:var(--dm-fg);transition:box-shadow .2s,transform .15s}
.dm-rq-retry.dm-on{box-shadow:var(--dm-shadow-pop)}
@media (hover:hover) and (pointer:fine){.dm-rq-retry:hover{box-shadow:var(--dm-shadow-pop)}}
.dm-rq-retry:active{transform:scale(.96)}
/* the end: every job done, said once in green where the running job was */
.dm-rq-fin{display:flex;align-items:center;gap:10px;padding:10px;border-radius:var(--dm-r-in);background:var(--dm-ok-bg)}
.dm-rq-fin .dm-rq-av{background:var(--dm-surface);color:var(--dm-ok)}
.dm-rq-fin b{font-weight:500;color:var(--dm-ok)}
.dm-rq-fin .dm-rq-js{color:var(--dm-fg2)}
.dm-rq-say{position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@container (max-width:340px){.dm-rq-h{flex-wrap:wrap}.dm-rq-jb,.dm-rq-steps{padding-left:0}}
:root:not([data-style="soft"]) .dm-rq-j:is([data-s="run"],[data-s="fail"]):not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 70%,transparent)}
:root:not([data-style="soft"]) .dm-rq-j[data-s="run"]:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,transparent)}
:root:not([data-style="soft"]) .dm-rq-j[data-s="fail"]:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(135deg,transparent 0 5px,color-mix(in srgb,var(--dm-bad) 10%,transparent) 5px 6px),var(--dm-bad-bg);box-shadow:none}
:root:not([data-style="soft"]) .dm-rq-bar i:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .dm-rq-tot b:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .2s steps(2,end)}
:root:not([data-style="soft"]) .dm-rq-retry:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 70%,transparent)}
